-- ============ THE ROUTE CATALOGUE ============
-- Every trekking route in Nepal we can guide, one row each. Route pages are
-- built entirely from these columns, so adding a route is adding a row — no
-- deploy, no template, no code. That is the whole point of the shape.
--
-- Day stops are the real overnight villages with their real altitudes;
-- coordinates are approximate village positions, accurate enough to draw the
-- line and pin the days. Month profiles are crowds/weather/cost on 1-5, and
-- they are honest about October being both the best weather and the worst
-- crowds on the popular trails.
--
-- Runs after seed.sql (see sql_paths in config.toml).


insert into public.routes (slug, name, region, typical_days, max_altitude_m, difficulty,
  requires_licensed_guide, season_months, distance_km, summary, start_point, end_point,
  sort, day_stops, month_profile, faq)
values ('everest-base-camp', 'Everest Base Camp', 'Khumbu', 14, 5644,
  'hard', true, '{3,4,5,10,11}', 130.0,
  'The walk everyone means when they say they are going to Everest: Lukla to Base Camp and the sunrise off Kala Patthar, through Namche, Tengboche and the Khumbu glacier.', 'Lukla', 'Lukla', 1,
  '[{"day":1,"place":"Phakding","altitude_m":2610,"lng":86.712,"lat":27.744,"note":"Short walk down the valley to shake the flight off."},{"day":2,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"The big climb, and the first sight of Everest from the ridge."},{"day":3,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"Acclimatisation day — walk high to Everest View, sleep low."},{"day":4,"place":"Tengboche","altitude_m":3860,"lng":86.764,"lat":27.836,"note":"Down to the river, up through rhododendron to the monastery."},{"day":5,"place":"Dingboche","altitude_m":4410,"lng":86.831,"lat":27.891,"note":"Above the treeline. The air changes today."},{"day":6,"place":"Dingboche","altitude_m":4410,"lng":86.831,"lat":27.891,"note":"Second acclimatisation day — Nangkartshang for the afternoon."},{"day":7,"place":"Lobuche","altitude_m":4940,"lng":86.81,"lat":27.948,"note":"Past the memorials at Thukla pass."},{"day":8,"place":"Gorak Shep","altitude_m":5164,"lng":86.828,"lat":27.981,"note":"Morning to Gorak Shep, afternoon to Base Camp and back."},{"day":9,"place":"Kala Patthar","altitude_m":5644,"lng":86.828,"lat":27.988,"note":"Up in the dark for sunrise on Everest, then down to Pheriche."},{"day":10,"place":"Pheriche","altitude_m":4270,"lng":86.819,"lat":27.895,"note":"Losing height fast now, and it feels wonderful."},{"day":11,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"Back below the treeline, and the first hot shower."},{"day":12,"place":"Lukla","altitude_m":2860,"lng":86.729,"lat":27.687,"note":"The last long day down the valley."},{"day":13,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly out, weather permitting — this is why we build in a buffer."},{"day":14,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Spare day for the Lukla flight. You will be glad of it."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":10,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Do I need a guide for Everest Base Camp?","a":"Yes. Since 2023 a licensed guide is required for foreign trekkers in Nepal''s national parks, including Sagarmatha. Every Trek guide holds a current TAAN licence and it is on their profile with the date it was checked."},{"q":"How fit do I need to be?","a":"If you can walk six to seven hours on a hill day, back to back, you are fit enough. Altitude matters more than fitness — the itinerary above has two acclimatisation days built in for that reason."},{"q":"What happens if I get altitude sickness?","a":"Your guide checks you every evening and carries a pulse oximeter. If you are unwell you descend, which is the treatment. Descending is not a failed trek; it is the plan working."}]'::jsonb)
