values ('gokyo-lakes', 'Gokyo Lakes', 'Khumbu', 12, 5357,
  'hard', true, '{3,4,5,10,11}', 92.0,
  'Six turquoise lakes under the biggest glacier in Nepal, and the finest view of Everest there is — from Gokyo Ri, away from the Base Camp queue.', 'Lukla', 'Lukla', 2,
  '[{"day":1,"place":"Phakding","altitude_m":2610,"lng":86.712,"lat":27.744,"note":"Same start as Base Camp, gentler crowd."},{"day":2,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"The hill to Namche. Slow is the only way up it."},{"day":3,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"Acclimatisation — up to Khumjung and back."},{"day":4,"place":"Dole","altitude_m":4040,"lng":86.7,"lat":27.876,"note":"Leave the Base Camp trail. It goes quiet almost at once."},{"day":5,"place":"Machhermo","altitude_m":4470,"lng":86.703,"lat":27.93,"note":"Short day on purpose. The altitude is doing the work."},{"day":6,"place":"Gokyo","altitude_m":4790,"lng":86.695,"lat":27.955,"note":"Past the first and second lakes to the village on the third."},{"day":7,"place":"Gokyo Ri","altitude_m":5357,"lng":86.69,"lat":27.962,"note":"Up in the dark. Everest, Lhotse and Makalu at once."},{"day":8,"place":"Gokyo","altitude_m":4790,"lng":86.695,"lat":27.955,"note":"Fourth and fifth lakes, or a rest day. Your call."},{"day":9,"place":"Dole","altitude_m":4040,"lng":86.7,"lat":27.876,"note":"Back down the valley."},{"day":10,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"Bakery day."},{"day":11,"place":"Lukla","altitude_m":2860,"lng":86.729,"lat":27.687,"note":"Long descent."},{"day":12,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly out."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":10,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Is Gokyo easier than Base Camp?","a":"Not easier, but quieter, and the view of Everest from Gokyo Ri is better than anything on the Base Camp side. Same altitude risk, same acclimatisation rules."},{"q":"Can I combine Gokyo with Base Camp?","a":"Yes, over the Cho La pass — that is the Three Passes trek''s western half. Add four or five days and expect a serious pass crossing."}]'::jsonb)
