values ('three-passes', 'Everest Three Passes', 'Khumbu', 19, 5545,
  'strenuous', true, '{3,4,5,10,11}', 166.0,
  'Renjo La, Cho La and Kongma La in one loop, taking in Gokyo, Base Camp and Chhukhung. The hardest thing in the Khumbu that is still a trek and not a climb.', 'Lukla', 'Lukla', 3,
  '[{"day":1,"place":"Phakding","altitude_m":2610,"lng":86.712,"lat":27.744,"note":"Down the valley."},{"day":2,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"The Namche hill."},{"day":3,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"Acclimatisation."},{"day":4,"place":"Thame","altitude_m":3800,"lng":86.629,"lat":27.837,"note":"West up the Bhote Kosi, almost nobody here."},{"day":5,"place":"Lungden","altitude_m":4380,"lng":86.599,"lat":27.916,"note":"Last village before the first pass."},{"day":6,"place":"Gokyo","altitude_m":4790,"lng":86.695,"lat":27.955,"note":"Renjo La, 5,360 m. The lakes appear all at once below you."},{"day":7,"place":"Gokyo Ri","altitude_m":5357,"lng":86.69,"lat":27.962,"note":"Sunrise, then a rest afternoon."},{"day":8,"place":"Thagnak","altitude_m":4700,"lng":86.716,"lat":27.947,"note":"Across the Ngozumpa glacier."},{"day":9,"place":"Dzongla","altitude_m":4830,"lng":86.774,"lat":27.936,"note":"Cho La, 5,420 m. Ice on the pass, rope sometimes."},{"day":10,"place":"Lobuche","altitude_m":4940,"lng":86.81,"lat":27.948,"note":"Short day onto the main trail."},{"day":11,"place":"Gorak Shep","altitude_m":5164,"lng":86.828,"lat":27.981,"note":"Base Camp in the afternoon."},{"day":12,"place":"Gorak Shep","altitude_m":5164,"lng":86.828,"lat":27.988,"note":"Kala Patthar at dawn."},{"day":13,"place":"Chhukhung","altitude_m":4730,"lng":86.9,"lat":27.899,"note":"Kongma La, 5,545 m. The hardest of the three."},{"day":14,"place":"Chhukhung Ri","altitude_m":5550,"lng":86.907,"lat":27.905,"note":"Optional summit day, or rest."},{"day":15,"place":"Dingboche","altitude_m":4410,"lng":86.831,"lat":27.891,"note":"Down into the Imja valley."},{"day":16,"place":"Tengboche","altitude_m":3860,"lng":86.764,"lat":27.836,"note":"Monastery, and trees again."},{"day":17,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"Almost home."},{"day":18,"place":"Lukla","altitude_m":2860,"lng":86.729,"lat":27.687,"note":"The last descent."},{"day":19,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly out."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":10,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"How hard is this really?","a":"Three passes over 5,300 m in a fortnight, with ice on Cho La in most seasons. You want previous multi-day trekking, a head for exposure, and a guide who has done it repeatedly — ask on their profile how many times."},{"q":"Do I need crampons?","a":"Microspikes are usually enough for Cho La in season. Your guide will tell you what the pass is doing that week — conditions change year to year."}]'::jsonb)
