values ('annapurna-circuit', 'Annapurna Circuit', 'Annapurna', 16, 5416,
  'hard', true, '{3,4,5,10,11}', 160.0,
  'Around the whole massif and over Thorong La, from subtropical river valleys to the Tibetan dryness of Mustang. The classic long walk in Nepal.', 'Besisahar', 'Jomsom', 4,
  '[{"day":1,"place":"Bhulbhule","altitude_m":840,"lng":84.399,"lat":28.283,"note":"Rice terraces, waterfalls, warm air."},{"day":2,"place":"Jagat","altitude_m":1300,"lng":84.376,"lat":28.418,"note":"Into the gorge."},{"day":3,"place":"Dharapani","altitude_m":1860,"lng":84.353,"lat":28.529,"note":"The Manaslu trail joins from the east."},{"day":4,"place":"Chame","altitude_m":2710,"lng":84.238,"lat":28.549,"note":"Pine forest, first snow peaks."},{"day":5,"place":"Upper Pisang","altitude_m":3300,"lng":84.157,"lat":28.617,"note":"Take the high route. It is worth the climb."},{"day":6,"place":"Manang","altitude_m":3520,"lng":84.019,"lat":28.667,"note":"Through Ghyaru and Ngawal, the best day on the circuit."},{"day":7,"place":"Manang","altitude_m":3520,"lng":84.019,"lat":28.667,"note":"Acclimatisation — Ice Lake or Gangapurna."},{"day":8,"place":"Yak Kharka","altitude_m":4050,"lng":84.005,"lat":28.72,"note":"Short and slow. Altitude day."},{"day":9,"place":"Thorong Phedi","altitude_m":4450,"lng":83.972,"lat":28.77,"note":"The foot of the pass. Early night."},{"day":10,"place":"Muktinath","altitude_m":3800,"lng":83.872,"lat":28.817,"note":"Thorong La, 5,416 m, in the dark and the cold."},{"day":11,"place":"Kagbeni","altitude_m":2810,"lng":83.783,"lat":28.836,"note":"Down into Mustang. The wind arrives at eleven."},{"day":12,"place":"Marpha","altitude_m":2670,"lng":83.686,"lat":28.754,"note":"Apple country. Apple brandy country."},{"day":13,"place":"Jomsom","altitude_m":2720,"lng":83.732,"lat":28.78,"note":"Short day, or fly out from here."},{"day":14,"place":"Tatopani","altitude_m":1200,"lng":83.65,"lat":28.497,"note":"Hot springs, and thick air again."},{"day":15,"place":"Ghorepani","altitude_m":2860,"lng":83.69,"lat":28.4,"note":"Back up for Poon Hill."},{"day":16,"place":"Pokhara","altitude_m":820,"lng":83.986,"lat":28.209,"note":"Poon Hill at dawn, then down and out."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":10,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Has the road ruined the Annapurna Circuit?","a":"There is a road for much of it now. It has not ruined the trek, but it changes who you walk with: a guide who knows the NATT footpath variants keeps you off the jeep track for most of the route. Ask them how many days you will be on the road."},{"q":"Which way round?","a":"Anticlockwise, Besisahar to Jomsom. Clockwise means climbing 1,600 m to Thorong La from the Muktinath side in one push, badly acclimatised."},{"q":"Can I skip the first days by jeep?","a":"Yes, most people now jeep to Chame or Dharapani. It costs you the subtropical lower valley and saves three days."}]'::jsonb)
