values ('annapurna-base-camp', 'Annapurna Base Camp', 'Annapurna', 11, 4130,
  'moderate', true, '{3,4,5,9,10,11}', 70.0,
  'Into the Annapurna Sanctuary — a ring of six peaks closing overhead, reached through bamboo forest and the Modi Khola gorge.', 'Nayapul', 'Nayapul', 5,
  '[{"day":1,"place":"Ghandruk","altitude_m":1940,"lng":83.808,"lat":28.377,"note":"Stone Gurung village on the shoulder of the ridge."},{"day":2,"place":"Chhomrong","altitude_m":2170,"lng":83.816,"lat":28.418,"note":"Down and up the other side. The stairs are famous."},{"day":3,"place":"Bamboo","altitude_m":2310,"lng":83.847,"lat":28.454,"note":"Into the gorge, into the bamboo."},{"day":4,"place":"Deurali","altitude_m":3230,"lng":83.867,"lat":28.494,"note":"The valley narrows to a slot."},{"day":5,"place":"Annapurna Base Camp","altitude_m":4130,"lng":83.879,"lat":28.531,"note":"Through Machhapuchhre Base Camp and into the Sanctuary."},{"day":6,"place":"Bamboo","altitude_m":2310,"lng":83.847,"lat":28.454,"note":"Sunrise in the amphitheatre, then a long way down."},{"day":7,"place":"Jhinu Danda","altitude_m":1780,"lng":83.82,"lat":28.4,"note":"Hot springs by the river."},{"day":8,"place":"Pokhara","altitude_m":820,"lng":83.986,"lat":28.209,"note":"Out via Nayapul."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Is the Sanctuary safe in winter?","a":"Avalanche risk between Hinku Cave and Deurali is real in and after heavy snow. Guides who work this route watch it closely; in a bad year they will turn you around, and they should."},{"q":"Can I do this and Poon Hill together?","a":"Yes, and most do — Ghorepani and Poon Hill add two or three days on the way in."}]'::jsonb)
