values ('poon-hill', 'Ghorepani Poon Hill', 'Annapurna', 5, 3210,
  'easy', true, '{2,3,4,5,9,10,11,12}', 42.0,
  'The short one, and the reason a lot of people come back for the long ones: rhododendron forest, stone stairs and a sunrise over Dhaulagiri and Annapurna.', 'Nayapul', 'Nayapul', 6,
  '[{"day":1,"place":"Tikhedhunga","altitude_m":1540,"lng":83.749,"lat":28.348,"note":"Gentle river walk to start."},{"day":2,"place":"Ghorepani","altitude_m":2860,"lng":83.69,"lat":28.4,"note":"Three thousand stone steps to Ulleri. Everyone remembers them."},{"day":3,"place":"Tadapani","altitude_m":2630,"lng":83.74,"lat":28.398,"note":"Poon Hill at dawn, then across the ridge."},{"day":4,"place":"Ghandruk","altitude_m":1940,"lng":83.808,"lat":28.377,"note":"Down through moss forest to the Gurung village."},{"day":5,"place":"Pokhara","altitude_m":820,"lng":83.986,"lat":28.209,"note":"Out by jeep."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":3,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."}]'::jsonb, '[{"q":"Is Poon Hill too crowded?","a":"In late October it is busy at the viewpoint at dawn. Going in early March, or sleeping at Tadapani instead of Ghorepani, gets you most of the view and a fraction of the people."},{"q":"Is it suitable for children?","a":"Yes — this is the trek families do. Five days, teahouses throughout, nothing above 3,210 m."}]'::jsonb)
