values ('mardi-himal', 'Mardi Himal', 'Annapurna', 5, 4500,
  'moderate', true, '{2,3,4,5,9,10,11,12}', 45.0,
  'A hidden ridge under Machhapuchhre that almost nobody walked until 2012. Short, steep and startlingly close to the mountain.', 'Kande', 'Pokhara', 7,
  '[{"day":1,"place":"Forest Camp","altitude_m":2600,"lng":83.896,"lat":28.348,"note":"Straight up into rhododendron and moss."},{"day":2,"place":"Low Camp","altitude_m":2970,"lng":83.918,"lat":28.397,"note":"The forest thins and Machhapuchhre appears."},{"day":3,"place":"High Camp","altitude_m":3580,"lng":83.93,"lat":28.437,"note":"On the ridge now, exposed the whole way."},{"day":4,"place":"Viewpoint","altitude_m":4500,"lng":83.933,"lat":28.47,"note":"Up before dawn to the upper viewpoint, then down to Siding."},{"day":5,"place":"Pokhara","altitude_m":820,"lng":83.986,"lat":28.209,"note":"Jeep out from Siding."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":3,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."}]'::jsonb, '[{"q":"Why is Mardi Himal so quiet?","a":"It only opened as a teahouse trek in 2012 and it is short, so it gets skipped by people planning a big trip. That is exactly its appeal."},{"q":"Is High Camp cold?","a":"Yes — 3,580 m on an exposed ridge, and the lodges are basic. A proper sleeping bag matters here more than on the busier trails."}]'::jsonb)
