values ('manaslu-circuit', 'Manaslu Circuit', 'Manaslu', 14, 5106,
  'strenuous', true, '{3,4,5,9,10,11}', 177.0,
  'Around the eighth-highest mountain on earth, through a restricted area that keeps the numbers down. Larkya La is the highest pass on any teahouse circuit in Nepal.', 'Soti Khola', 'Dharapani', 8,
  '[{"day":1,"place":"Machha Khola","altitude_m":930,"lng":84.898,"lat":28.376,"note":"Hot, green and loud with the river."},{"day":2,"place":"Jagat","altitude_m":1340,"lng":84.892,"lat":28.463,"note":"Permit check. The restricted area starts here."},{"day":3,"place":"Deng","altitude_m":1860,"lng":84.851,"lat":28.556,"note":"The valley turns Tibetan."},{"day":4,"place":"Namrung","altitude_m":2630,"lng":84.766,"lat":28.583,"note":"Gompas, mani walls, chortens."},{"day":5,"place":"Lho","altitude_m":3180,"lng":84.7,"lat":28.611,"note":"First full view of Manaslu."},{"day":6,"place":"Samagaon","altitude_m":3530,"lng":84.622,"lat":28.615,"note":"The biggest village on the circuit."},{"day":7,"place":"Samagaon","altitude_m":3530,"lng":84.622,"lat":28.615,"note":"Acclimatisation — Birendra Lake or Manaslu Base Camp."},{"day":8,"place":"Samdo","altitude_m":3860,"lng":84.591,"lat":28.658,"note":"Short day, close to the Tibetan border."},{"day":9,"place":"Dharamsala","altitude_m":4460,"lng":84.526,"lat":28.658,"note":"Larkya Phedi. Cold, basic, one night only."},{"day":10,"place":"Bimthang","altitude_m":3590,"lng":84.427,"lat":28.617,"note":"Larkya La, 5,106 m. Long day, early start."},{"day":11,"place":"Dharapani","altitude_m":1860,"lng":84.353,"lat":28.529,"note":"Down through pine into the Annapurna valley."},{"day":12,"place":"Besisahar","altitude_m":760,"lng":84.377,"lat":28.231,"note":"Jeep out."},{"day":13,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Drive back."},{"day":14,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Buffer day."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":5,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Why do I need a permit and a guide here?","a":"Manaslu is a restricted area: you need a Restricted Area Permit, you must be in a group of at least two, and you must go with a licensed guide through a registered agency. Trek handles the paperwork; the RAP alone is USD 100 for the first week."},{"q":"Is Larkya La harder than Thorong La?","a":"Longer and more remote, with a rougher descent. The pass itself is not technical but the day is eight to ten hours and the lodge before it is the most basic on the circuit."}]'::jsonb)
