values ('tsum-valley', 'Tsum Valley', 'Manaslu', 14, 3700,
  'hard', true, '{3,4,5,9,10,11}', 120.0,
  'A hidden Buddhist valley off the Manaslu trail, sealed to outsiders until 2008. Monasteries, mani walls and a valley where killing animals is forbidden by ancient vow.', 'Soti Khola', 'Soti Khola', 9,
  '[{"day":1,"place":"Machha Khola","altitude_m":930,"lng":84.898,"lat":28.376,"note":"The Manaslu start."},{"day":2,"place":"Jagat","altitude_m":1340,"lng":84.892,"lat":28.463,"note":"Permit check."},{"day":3,"place":"Lokpa","altitude_m":2240,"lng":84.937,"lat":28.52,"note":"Turn east. Almost nobody follows."},{"day":4,"place":"Chumling","altitude_m":2386,"lng":84.964,"lat":28.549,"note":"First village of lower Tsum."},{"day":5,"place":"Chhokangparo","altitude_m":3010,"lng":85.008,"lat":28.588,"note":"Upper Tsum opens out. Ganesh Himal fills the sky."},{"day":6,"place":"Nile","altitude_m":3361,"lng":85.043,"lat":28.627,"note":"Past Milarepa''s cave."},{"day":7,"place":"Mu Gompa","altitude_m":3700,"lng":85.056,"lat":28.652,"note":"The highest monastery in the valley."},{"day":8,"place":"Rachen Gompa","altitude_m":3240,"lng":85.02,"lat":28.6,"note":"The nunnery on the way back."},{"day":9,"place":"Chumling","altitude_m":2386,"lng":84.964,"lat":28.549,"note":"Down the valley."},{"day":10,"place":"Philim","altitude_m":1570,"lng":84.905,"lat":28.487,"note":"Back on the Manaslu trail."},{"day":11,"place":"Machha Khola","altitude_m":930,"lng":84.898,"lat":28.376,"note":"Warm again."},{"day":12,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Long drive out."},{"day":13,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Buffer."},{"day":14,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Buffer."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Can I combine Tsum with the Manaslu Circuit?","a":"Yes, and it is the usual way to do it — about 21 to 24 days for both. Tsum alone is an out-and-back."},{"q":"What is the no-killing vow?","a":"Tsum is a beyul, a sacred hidden valley. The community took a vow against animal slaughter and hunting, and it holds. Expect no meat in the upper valley."}]'::jsonb)
