values ('langtang-valley', 'Langtang Valley', 'Langtang', 8, 4984,
  'moderate', true, '{3,4,5,10,11}', 62.0,
  'The closest big valley to Kathmandu, buried by a landslide in the 2015 earthquake and rebuilt by the people who survived it. Yak pastures, a cheese factory, and Kyanjin Ri above.', 'Syabrubesi', 'Syabrubesi', 10,
  '[{"day":1,"place":"Lama Hotel","altitude_m":2470,"lng":85.451,"lat":28.174,"note":"Steep river gorge, monkeys, bamboo."},{"day":2,"place":"Langtang village","altitude_m":3430,"lng":85.55,"lat":28.212,"note":"Past the memorial and the rebuilt houses."},{"day":3,"place":"Kyanjin Gompa","altitude_m":3870,"lng":85.565,"lat":28.211,"note":"Short day. The valley opens out completely."},{"day":4,"place":"Kyanjin Ri","altitude_m":4773,"lng":85.562,"lat":28.22,"note":"Up at dawn for the whole Langtang Lirung face."},{"day":5,"place":"Lama Hotel","altitude_m":2470,"lng":85.451,"lat":28.174,"note":"Long descent."},{"day":6,"place":"Syabrubesi","altitude_m":1460,"lng":85.336,"lat":28.163,"note":"Out to the road."},{"day":7,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Drive back."},{"day":8,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Buffer for the road."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Is Langtang safe after the earthquake?","a":"Yes. The trail was rebuilt and the lodges with it. The village that was buried has been rebuilt on a different site, and the memorial is on the trail — your guide will tell you about it if you ask, and many of them lost people there."},{"q":"Why go to Langtang instead of Everest or Annapurna?","a":"It is a seven-hour drive rather than a flight, it costs less, and it is emptier. For a first Himalayan trek with limited time it is hard to beat."}]'::jsonb)
