values ('gosaikunda', 'Gosaikunda', 'Langtang', 7, 4610,
  'moderate', true, '{3,4,5,10,11}', 55.0,
  'High sacred lakes at 4,380 m, frozen half the year and full of pilgrims each August. Often walked as a continuation of Langtang over the Laurebina pass.', 'Dhunche', 'Sundarijal', 11,
  '[{"day":1,"place":"Deurali","altitude_m":2600,"lng":85.29,"lat":28.107,"note":"Steep from the road, straight up the ridge."},{"day":2,"place":"Sing Gompa","altitude_m":3330,"lng":85.328,"lat":28.1,"note":"Cheese factory, rhododendron, first views."},{"day":3,"place":"Gosaikunda","altitude_m":4380,"lng":85.415,"lat":28.084,"note":"The lakes. Cold and completely still."},{"day":4,"place":"Ghopte","altitude_m":3440,"lng":85.472,"lat":28.052,"note":"Laurebina La, 4,610 m, then a long rough descent."},{"day":5,"place":"Kutumsang","altitude_m":2470,"lng":85.485,"lat":27.983,"note":"Ridge villages, back into forest."},{"day":6,"place":"Chisapani","altitude_m":2215,"lng":85.436,"lat":27.833,"note":"Last night on the ridge."},{"day":7,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Down to Sundarijal and a taxi home."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"When is the pilgrimage?","a":"Janai Purnima, in August — thousands of pilgrims walk up to bathe in the lake. Extraordinary to witness, and a bad week to want a quiet lodge."},{"q":"Can I combine it with Langtang?","a":"Yes. Langtang to Kyanjin, back down to Syabrubesi, then up to Gosaikunda and out over Laurebina — about 12 to 14 days."}]'::jsonb)
