values ('upper-mustang', 'Upper Mustang', 'Mustang', 14, 3840,
  'moderate', true, '{4,5,6,7,8,9,10}', 170.0,
  'The walled city of Lo Manthang and the old Tibetan kingdom behind the Himalaya. Dry, ochre, wind-blasted, and one of the few places in Nepal you can trek in the monsoon.', 'Jomsom', 'Jomsom', 12,
  '[{"day":1,"place":"Kagbeni","altitude_m":2810,"lng":83.783,"lat":28.836,"note":"The gate to Upper Mustang. Permit checked here."},{"day":2,"place":"Chele","altitude_m":3050,"lng":83.789,"lat":28.907,"note":"Red cliffs and cave dwellings."},{"day":3,"place":"Syangboche","altitude_m":3800,"lng":83.831,"lat":28.982,"note":"Two passes, no shade."},{"day":4,"place":"Ghami","altitude_m":3520,"lng":83.85,"lat":29.031,"note":"The longest mani wall in Nepal."},{"day":5,"place":"Tsarang","altitude_m":3560,"lng":83.897,"lat":29.073,"note":"Old fort and monastery on the cliff edge."},{"day":6,"place":"Lo Manthang","altitude_m":3840,"lng":83.957,"lat":29.183,"note":"Into the walled city."},{"day":7,"place":"Lo Manthang","altitude_m":3840,"lng":83.957,"lat":29.183,"note":"A day for the monasteries and Chhoser caves."},{"day":8,"place":"Dhakmar","altitude_m":3820,"lng":83.887,"lat":29.13,"note":"West route back, past red cliffs."},{"day":9,"place":"Ghiling","altitude_m":3570,"lng":83.822,"lat":28.976,"note":"Quiet villages."},{"day":10,"place":"Chhusang","altitude_m":2980,"lng":83.792,"lat":28.874,"note":"Back down the Kali Gandaki."},{"day":11,"place":"Jomsom","altitude_m":2720,"lng":83.732,"lat":28.78,"note":"Out."},{"day":12,"place":"Pokhara","altitude_m":820,"lng":83.986,"lat":28.209,"note":"Fly or drive."},{"day":13,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Onward."},{"day":14,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Buffer for Jomsom weather."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":7,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":8,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Why is Upper Mustang so expensive?","a":"The restricted-area permit is USD 500 per person for ten days, plus USD 50 a day after that. That goes to the government, not to us or your guide, and it appears as its own line in your price breakdown."},{"q":"Can I trek Mustang in the monsoon?","a":"Yes — it sits in the rain shadow behind the Himalaya. July and August are among the best months here while the rest of Nepal is under cloud."}]'::jsonb)
