values ('nar-phu', 'Nar Phu Valley', 'Annapurna', 12, 5320,
  'strenuous', true, '{3,4,5,9,10,11}', 106.0,
  'Two medieval Tibetan villages in a restricted side valley off the Annapurna Circuit, and the Kang La pass back over to Manang.', 'Koto', 'Manang', 13,
  '[{"day":1,"place":"Meta","altitude_m":3560,"lng":84.234,"lat":28.617,"note":"Into the gorge. Permit checked at Koto."},{"day":2,"place":"Phu","altitude_m":4080,"lng":84.303,"lat":28.752,"note":"The upper village, and the old dzong above it."},{"day":3,"place":"Phu","altitude_m":4080,"lng":84.303,"lat":28.752,"note":"Acclimatisation and Tashi Lhakhang gompa."},{"day":4,"place":"Nar","altitude_m":4110,"lng":84.23,"lat":28.674,"note":"Across to the second village."},{"day":5,"place":"Nar","altitude_m":4110,"lng":84.23,"lat":28.674,"note":"Rest before the pass."},{"day":6,"place":"Ngawal","altitude_m":3660,"lng":84.076,"lat":28.64,"note":"Kang La, 5,320 m, and down into the Annapurna valley."},{"day":7,"place":"Manang","altitude_m":3520,"lng":84.019,"lat":28.667,"note":"Back on the circuit."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Do I need a separate permit for Nar Phu?","a":"Yes — a restricted-area permit on top of ACAP, and you must go with a licensed guide. It is usually added to an Annapurna Circuit trek."},{"q":"How remote is it?","a":"Two villages, no road, no phone signal in most of the valley. Kang La is a serious pass and the weather closes it without much warning."}]'::jsonb)
