values ('kanchenjunga-base-camp', 'Kanchenjunga Base Camp', 'Kanchenjunga', 21, 5143,
  'strenuous', true, '{3,4,5,9,10,11}', 220.0,
  'The far east of Nepal, to the north and south base camps of the third-highest mountain on earth. Long, remote, and almost empty.', 'Taplejung', 'Taplejung', 14,
  '[{"day":1,"place":"Chiruwa","altitude_m":1270,"lng":87.93,"lat":27.55,"note":"Cardamom fields and river."},{"day":2,"place":"Sekathum","altitude_m":1660,"lng":87.938,"lat":27.633,"note":"Confluence of two valleys."},{"day":3,"place":"Amjilosa","altitude_m":2510,"lng":87.93,"lat":27.687,"note":"Steep and jungly."},{"day":4,"place":"Gyabla","altitude_m":2730,"lng":87.93,"lat":27.72,"note":"Cloud forest."},{"day":5,"place":"Ghunsa","altitude_m":3595,"lng":87.938,"lat":27.66,"note":"Tibetan village, and a rest day here."},{"day":6,"place":"Ghunsa","altitude_m":3595,"lng":87.938,"lat":27.66,"note":"Acclimatisation."},{"day":7,"place":"Khambachen","altitude_m":4050,"lng":88.005,"lat":27.7,"note":"The valley opens to the north."},{"day":8,"place":"Lhonak","altitude_m":4790,"lng":88.055,"lat":27.732,"note":"High, cold and treeless."},{"day":9,"place":"Pangpema","altitude_m":5143,"lng":88.1,"lat":27.76,"note":"North Base Camp, under the Kanchenjunga face."},{"day":10,"place":"Ghunsa","altitude_m":3595,"lng":87.938,"lat":27.66,"note":"Back down."},{"day":11,"place":"Sele Le","altitude_m":4290,"lng":87.895,"lat":27.61,"note":"Up towards the passes."},{"day":12,"place":"Tseram","altitude_m":3870,"lng":87.87,"lat":27.545,"note":"Over Sinion La and Mirgin La."},{"day":13,"place":"Ramche","altitude_m":4580,"lng":87.885,"lat":27.51,"note":"South side now."},{"day":14,"place":"Oktang","altitude_m":4730,"lng":87.9,"lat":27.495,"note":"South Base Camp and the Yalung glacier."},{"day":15,"place":"Tortong","altitude_m":2995,"lng":87.845,"lat":27.52,"note":"Long descent."},{"day":16,"place":"Yamphudin","altitude_m":2080,"lng":87.8,"lat":27.48,"note":"First real village in days."},{"day":17,"place":"Khebang","altitude_m":1910,"lng":87.76,"lat":27.42,"note":"Terraced hills."},{"day":18,"place":"Taplejung","altitude_m":1820,"lng":87.67,"lat":27.35,"note":"Out to the road."},{"day":19,"place":"Bhadrapur","altitude_m":300,"lng":88.08,"lat":26.57,"note":"Long drive to the plains."},{"day":20,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly."},{"day":21,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Buffer."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"How remote is Kanchenjunga?","a":"Three days from the nearest hospital in places, and a restricted area requiring a permit and a licensed guide. Helicopter evacuation is weather-dependent and expensive; insurance covering it is not optional."},{"q":"North or south base camp?","a":"Both, if you have 21 days — the traverse over Sele Le links them. North (Pangpema) alone is about 16 days."}]'::jsonb)
