values ('makalu-barun', 'Makalu Base Camp', 'Makalu', 18, 4870,
  'strenuous', true, '{3,4,5,9,10,11}', 150.0,
  'Through rhododendron forest and the Barun valley to the base of the fifth-highest mountain. One of the least-walked big treks in Nepal.', 'Num', 'Num', 15,
  '[{"day":1,"place":"Seduwa","altitude_m":1500,"lng":87.235,"lat":27.5,"note":"Down to the river and back up the far side."},{"day":2,"place":"Tashigaon","altitude_m":2100,"lng":87.245,"lat":27.545,"note":"The last permanent village."},{"day":3,"place":"Khongma Danda","altitude_m":3560,"lng":87.27,"lat":27.59,"note":"Brutal climb, wonderful ridge."},{"day":4,"place":"Dobato","altitude_m":3800,"lng":87.3,"lat":27.63,"note":"Over Shipton La in cloud, usually."},{"day":5,"place":"Yangle Kharka","altitude_m":3600,"lng":87.32,"lat":27.7,"note":"Into the Barun valley proper."},{"day":6,"place":"Langmale Kharka","altitude_m":4410,"lng":87.38,"lat":27.76,"note":"Herders'' huts and moraine."},{"day":7,"place":"Makalu Base Camp","altitude_m":4870,"lng":87.42,"lat":27.8,"note":"Makalu straight overhead."},{"day":8,"place":"Makalu Base Camp","altitude_m":4870,"lng":87.42,"lat":27.8,"note":"A day to walk up the glacier."},{"day":9,"place":"Yangle Kharka","altitude_m":3600,"lng":87.32,"lat":27.7,"note":"Back down."},{"day":10,"place":"Dobato","altitude_m":3800,"lng":87.3,"lat":27.63,"note":"Up over the passes again."},{"day":11,"place":"Tashigaon","altitude_m":2100,"lng":87.245,"lat":27.545,"note":"The long knee-destroying descent."},{"day":12,"place":"Num","altitude_m":1560,"lng":87.23,"lat":27.545,"note":"Out to the road."},{"day":13,"place":"Tumlingtar","altitude_m":400,"lng":87.195,"lat":27.315,"note":"Drive down."},{"day":14,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Why is Makalu so quiet?","a":"It is hard to reach, the weather is worse than the Khumbu, and there are almost no lodges above Tashigaon — much of it is camping or herders'' huts. That is also why it is extraordinary."},{"q":"Do I need to camp?","a":"Some sections, yes. Basic teahouses exist as far as Yangle Kharka in season; above that expect huts or tents."}]'::jsonb)
