values ('dhaulagiri-circuit', 'Dhaulagiri Circuit', 'Dhaulagiri', 18, 5360,
  'strenuous', true, '{4,5,9,10}', 120.0,
  'A full camping traverse around the seventh-highest mountain, over French Pass and Dhampus Pass. No teahouses, no bail-outs after day five.', 'Beni', 'Marpha', 16,
  '[{"day":1,"place":"Babiachaur","altitude_m":950,"lng":83.52,"lat":28.41,"note":"River valley, warm."},{"day":2,"place":"Dharapani","altitude_m":1560,"lng":83.48,"lat":28.48,"note":"Terraces and villages."},{"day":3,"place":"Muri","altitude_m":1850,"lng":83.45,"lat":28.53,"note":"Last big village."},{"day":4,"place":"Boghara","altitude_m":2080,"lng":83.42,"lat":28.58,"note":"The gorge starts."},{"day":5,"place":"Dobang","altitude_m":2520,"lng":83.4,"lat":28.63,"note":"Forest camp."},{"day":6,"place":"Italian Base Camp","altitude_m":3660,"lng":83.43,"lat":28.68,"note":"Under the west face."},{"day":7,"place":"Italian Base Camp","altitude_m":3660,"lng":83.43,"lat":28.68,"note":"Acclimatisation day."},{"day":8,"place":"Glacier Camp","altitude_m":4200,"lng":83.47,"lat":28.7,"note":"On the moraine."},{"day":9,"place":"Dhaulagiri Base Camp","altitude_m":4740,"lng":83.5,"lat":28.71,"note":"The whole north face above camp."},{"day":10,"place":"Hidden Valley","altitude_m":5140,"lng":83.55,"lat":28.74,"note":"French Pass, 5,360 m."},{"day":11,"place":"Yak Kharka","altitude_m":3680,"lng":83.6,"lat":28.72,"note":"Dhampus Pass, then a huge descent."},{"day":12,"place":"Marpha","altitude_m":2670,"lng":83.686,"lat":28.754,"note":"Apple orchards and a bed."},{"day":13,"place":"Pokhara","altitude_m":820,"lng":83.986,"lat":28.209,"note":"Out via Jomsom."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Is this a teahouse trek?","a":"No. From Boghara onwards it is fully supported camping with a crew. That is why it costs more than the circuits and why the group size matters."},{"q":"What is the hardest part?","a":"Hidden Valley at 5,140 m, camped, after French Pass. If the weather turns there the options are limited, which is why the guide''s judgement matters more here than on any teahouse route."}]'::jsonb)
