values ('rara-lake', 'Rara Lake', 'Karnali', 10, 3200,
  'moderate', true, '{4,5,6,9,10}', 80.0,
  'The biggest lake in Nepal, at 2,990 m in the far west, ringed by blue pine and almost never visited. Trekking in a part of the country tourism has barely reached.', 'Jumla', 'Jumla', 17,
  '[{"day":1,"place":"Chere Chaur","altitude_m":3055,"lng":82.22,"lat":29.29,"note":"Straight up out of Jumla."},{"day":2,"place":"Chalachaur","altitude_m":2980,"lng":82.16,"lat":29.36,"note":"Pine forest and herders."},{"day":3,"place":"Sinja","altitude_m":2400,"lng":82.1,"lat":29.42,"note":"The old Khas capital."},{"day":4,"place":"Ghorosingha","altitude_m":3050,"lng":82.06,"lat":29.48,"note":"Ridge walking."},{"day":5,"place":"Rara Lake","altitude_m":2990,"lng":82.088,"lat":29.52,"note":"The lake appears all at once."},{"day":6,"place":"Rara Lake","altitude_m":2990,"lng":82.088,"lat":29.52,"note":"A day to walk the shore and up Murma Top."},{"day":7,"place":"Pina","altitude_m":2400,"lng":82.15,"lat":29.56,"note":"East out of the park."},{"day":8,"place":"Bumra","altitude_m":2850,"lng":82.22,"lat":29.48,"note":"Back over the ridges."},{"day":9,"place":"Jumla","altitude_m":2540,"lng":82.183,"lat":29.274,"note":"Out."},{"day":10,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly via Nepalgunj."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"How do I get to Jumla?","a":"Fly Kathmandu to Nepalgunj, then a small plane to Jumla. Both legs are weather-dependent, so build in a spare day at each end."},{"q":"Is there accommodation?","a":"Basic lodges and homestays, plus a couple of places at the lake itself. This is not the Khumbu — expect simple food and shared rooms."}]'::jsonb)
