values ('khopra-danda', 'Khopra Danda', 'Annapurna', 9, 4660,
  'moderate', true, '{3,4,5,10,11}', 60.0,
  'A community-run ridge trek above the Poon Hill trail, with the option of Khayer Lake at 4,660 m. Empty trails a day''s walk from the busiest ones in Nepal.', 'Nayapul', 'Nayapul', 18,
  '[{"day":1,"place":"Ulleri","altitude_m":2050,"lng":83.73,"lat":28.37,"note":"The stone stairs again."},{"day":2,"place":"Ghorepani","altitude_m":2860,"lng":83.69,"lat":28.4,"note":"Rhododendron forest."},{"day":3,"place":"Chistibung","altitude_m":3050,"lng":83.64,"lat":28.44,"note":"Leave the crowds behind at the junction."},{"day":4,"place":"Khopra Danda","altitude_m":3660,"lng":83.618,"lat":28.47,"note":"The ridge lodge, with Dhaulagiri filling the west."},{"day":5,"place":"Khayer Lake","altitude_m":4660,"lng":83.6,"lat":28.52,"note":"Long day up to the sacred lake and back."},{"day":6,"place":"Swanta","altitude_m":2200,"lng":83.66,"lat":28.43,"note":"Down into the village."},{"day":7,"place":"Ghandruk","altitude_m":1940,"lng":83.808,"lat":28.377,"note":"Across the hillside."},{"day":8,"place":"Pokhara","altitude_m":820,"lng":83.986,"lat":28.209,"note":"Out."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"What makes it community-run?","a":"The lodges on the ridge are owned and run collectively by the villages below, and the money stays there. It is one of the few routes where where your money goes is visible on the trail."},{"q":"Is Khayer Lake hard?","a":"It is a 1,000 m ascent and descent in one day at altitude, on scree. Optional, and plenty of people sensibly skip it."}]'::jsonb)
