values ('pikey-peak', 'Pikey Peak', 'Solukhumbu', 7, 4065,
  'easy', true, '{2,3,4,5,9,10,11,12}', 55.0,
  'Low-altitude Solu, Sherpa villages and the viewpoint Hillary said was his favourite in Nepal — eight thousanders from Kanchenjunga to Dhaulagiri.', 'Dhap', 'Phaplu', 19,
  '[{"day":1,"place":"Jhapre","altitude_m":2820,"lng":86.395,"lat":27.56,"note":"Ridge from the road, prayer flags all the way."},{"day":2,"place":"Pikey Base Camp","altitude_m":3640,"lng":86.4,"lat":27.615,"note":"Yak pasture under the summit."},{"day":3,"place":"Pikey Peak","altitude_m":4065,"lng":86.405,"lat":27.63,"note":"Sunrise from the top, then down to Jhapre."},{"day":4,"place":"Junbesi","altitude_m":2675,"lng":86.56,"lat":27.56,"note":"Beautiful Sherpa village and monastery."},{"day":5,"place":"Phaplu","altitude_m":2470,"lng":86.585,"lat":27.517,"note":"Out to the airstrip."},{"day":6,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly or drive."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."}]'::jsonb, '[{"q":"Why Pikey instead of Everest Base Camp?","a":"No altitude risk, no Lukla flight, teahouses the whole way, and a view that takes in most of the Himalaya at once. For a first trek or a short trip it is the best value in Nepal."},{"q":"When is the festival?","a":"Mani Rimdu at Chiwong monastery, near Phaplu, falls in October or November. Worth planning around."}]'::jsonb)
