values ('everest-view-tengboche', 'Everest View & Tengboche', 'Khumbu', 8, 3860,
  'moderate', true, '{3,4,5,10,11}', 42.0,
  'The Khumbu without the altitude: Namche, Khumjung, the Everest View Hotel and Tengboche monastery, turning around before the air gets thin.', 'Lukla', 'Lukla', 20,
  '[{"day":1,"place":"Phakding","altitude_m":2610,"lng":86.712,"lat":27.744,"note":"Down the valley from Lukla."},{"day":2,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"The hill, and the first sight of Everest."},{"day":3,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"Acclimatisation to Everest View Hotel and Khumjung."},{"day":4,"place":"Tengboche","altitude_m":3860,"lng":86.764,"lat":27.836,"note":"The monastery, and the best-placed teahouse in Nepal."},{"day":5,"place":"Namche Bazaar","altitude_m":3440,"lng":86.714,"lat":27.804,"note":"Back down, with the whole valley ahead of you."},{"day":6,"place":"Lukla","altitude_m":2860,"lng":86.729,"lat":27.687,"note":"The last walk."},{"day":7,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly out."},{"day":8,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Buffer for Lukla weather."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Will I actually see Everest?","a":"Yes — from the ridge above Namche, from Everest View Hotel, and from Tengboche, weather permitting. You just do not stand at the bottom of it."},{"q":"Is this suitable for older trekkers or families?","a":"It is the Khumbu trek we most often suggest for both. Nothing above 3,860 m, proper lodges, and short days."}]'::jsonb)
