values ('helambu', 'Helambu', 'Langtang', 6, 3650,
  'easy', true, '{2,3,4,5,9,10,11,12}', 50.0,
  'Sherpa and Tamang villages a day''s walk from Kathmandu, through rhododendron and terraced hillside. The trek you do when you have a week and no flight.', 'Sundarijal', 'Melamchi', 21,
  '[{"day":1,"place":"Chisapani","altitude_m":2215,"lng":85.436,"lat":27.833,"note":"Out of the valley on the Shivapuri ridge."},{"day":2,"place":"Kutumsang","altitude_m":2470,"lng":85.485,"lat":27.983,"note":"Ridge villages, big views north."},{"day":3,"place":"Tharepati","altitude_m":3650,"lng":85.5,"lat":28.03,"note":"The high point, and the Gosaikunda junction."},{"day":4,"place":"Tarke Ghyang","altitude_m":2600,"lng":85.56,"lat":28.0,"note":"Down into Sherpa Helambu."},{"day":5,"place":"Melamchi","altitude_m":850,"lng":85.57,"lat":27.83,"note":"Out through the villages to the road."},{"day":6,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Two hours back."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":3,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":12,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."}]'::jsonb, '[{"q":"How close is it to Kathmandu?","a":"You start at Sundarijal, forty minutes from Thamel, and finish at a road head two hours away. No flights and no long drives."},{"q":"Can I extend it?","a":"Yes — from Tharepati you can carry on north to Gosaikunda and Langtang, which makes a two-week loop."}]'::jsonb)
