values ('lower-dolpo', 'Lower Dolpo', 'Dolpa', 17, 5190,
  'strenuous', true, '{5,6,7,8,9,10}', 180.0,
  'Shey Phoksundo, the deepest lake in Nepal, and the passes beyond it. Trans-Himalayan, Tibetan in culture, and the setting of Peter Matthiessen''s The Snow Leopard.', 'Juphal', 'Juphal', 22,
  '[{"day":1,"place":"Dunai","altitude_m":2140,"lng":82.92,"lat":28.93,"note":"The district headquarters, such as it is."},{"day":2,"place":"Ankhe","altitude_m":2660,"lng":82.87,"lat":28.98,"note":"Into the gorge."},{"day":3,"place":"Renje","altitude_m":3010,"lng":82.9,"lat":29.04,"note":"Forest and cliff path."},{"day":4,"place":"Phoksundo Lake","altitude_m":3610,"lng":82.94,"lat":29.185,"note":"The waterfall, then the lake. The colour is not exaggerated."},{"day":5,"place":"Phoksundo Lake","altitude_m":3610,"lng":82.94,"lat":29.185,"note":"A day at the lake and Ringmo village."},{"day":6,"place":"Phoksundo Khola","altitude_m":3630,"lng":82.98,"lat":29.23,"note":"The famous cliff ledge path along the lake."},{"day":7,"place":"Snowfields Camp","altitude_m":4400,"lng":83.03,"lat":29.27,"note":"Up the valley towards the pass."},{"day":8,"place":"Baga La Base","altitude_m":4750,"lng":83.07,"lat":29.24,"note":"High camp."},{"day":9,"place":"Numa La Base","altitude_m":4440,"lng":83.1,"lat":29.19,"note":"Baga La, 5,190 m."},{"day":10,"place":"Dho Tarap","altitude_m":4090,"lng":83.18,"lat":29.13,"note":"Numa La, 5,160 m, then down to the village."},{"day":11,"place":"Dho Tarap","altitude_m":4090,"lng":83.18,"lat":29.13,"note":"Rest and the monasteries."},{"day":12,"place":"Tarap Khola","altitude_m":3800,"lng":83.12,"lat":29.06,"note":"Down the gorge."},{"day":13,"place":"Khanigaon","altitude_m":3110,"lng":83.03,"lat":28.99,"note":"Narrowing valley."},{"day":14,"place":"Dunai","altitude_m":2140,"lng":82.92,"lat":28.93,"note":"Back to the road."},{"day":15,"place":"Juphal","altitude_m":2490,"lng":82.89,"lat":28.92,"note":"Up to the airstrip."},{"day":16,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly via Nepalgunj."},{"day":17,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Buffer — Juphal flights are unreliable."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":4,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":7,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":8,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Is Dolpo restricted?","a":"Lower Dolpo needs a restricted-area permit (USD 20 per week) plus the Shey Phoksundo National Park fee. Upper Dolpo is USD 500 for ten days and a different trek entirely."},{"q":"Camping or teahouse?","a":"Mostly camping with a crew. There are a few simple lodges at Ringmo and Dho Tarap; everything between is tents."}]'::jsonb)
