values ('api-base-camp', 'Api Base Camp', 'Sudurpashchim', 14, 4100,
  'strenuous', true, '{4,5,9,10}', 110.0,
  'The far north-west corner of Nepal, under Api at 7,132 m. Almost no foreign trekkers come here at all.', 'Gokuleshwar', 'Gokuleshwar', 23,
  '[{"day":1,"place":"Makarighat","altitude_m":1100,"lng":80.76,"lat":29.72,"note":"River and rice."},{"day":2,"place":"Seti","altitude_m":1550,"lng":80.72,"lat":29.79,"note":"Villages on the hillside."},{"day":3,"place":"Dhaulakot","altitude_m":1900,"lng":80.7,"lat":29.85,"note":"Steep forest."},{"day":4,"place":"Ghusa","altitude_m":2100,"lng":80.68,"lat":29.91,"note":"Last village of size."},{"day":5,"place":"Bugjyani","altitude_m":3200,"lng":80.66,"lat":29.96,"note":"Above the treeline."},{"day":6,"place":"Api Base Camp","altitude_m":4100,"lng":80.64,"lat":30.01,"note":"Under the south face."},{"day":7,"place":"Api Base Camp","altitude_m":4100,"lng":80.64,"lat":30.01,"note":"A day to walk the moraine."},{"day":8,"place":"Ghusa","altitude_m":2100,"lng":80.68,"lat":29.91,"note":"Down."},{"day":9,"place":"Seti","altitude_m":1550,"lng":80.72,"lat":29.79,"note":"Retracing."},{"day":10,"place":"Gokuleshwar","altitude_m":950,"lng":80.78,"lat":29.7,"note":"Out to the road."},{"day":11,"place":"Dhangadhi","altitude_m":190,"lng":80.59,"lat":28.7,"note":"Long drive south."},{"day":12,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":4,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":7,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":8,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":3,"weather":5,"cost":4,"note":"Peak season — book early."},{"m":11,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"Why does nobody go here?","a":"It is three days of travel from Kathmandu before you start walking, and there is almost no trekking infrastructure. Go for exactly that reason, or do not go."},{"q":"What is the accommodation?","a":"Homestays and camping. Your guide arranges village stays — expect floor space, dal bhat and considerable curiosity."}]'::jsonb)
