values ('badimalika', 'Badimalika', 'Sudurpashchim', 9, 4200,
  'moderate', true, '{5,6,7,8,9}', 70.0,
  'A pilgrimage trek to a temple at 4,200 m in the far west, through alpine meadow that turns solid with pilgrims each August for Janai Purnima.', 'Martadi', 'Martadi', 24,
  '[{"day":1,"place":"Jharjharia","altitude_m":1800,"lng":81.5,"lat":29.4,"note":"Out of the bazaar and up."},{"day":2,"place":"Dhaulapani","altitude_m":2600,"lng":81.47,"lat":29.45,"note":"Terraces give way to forest."},{"day":3,"place":"Nyaulpani","altitude_m":3200,"lng":81.44,"lat":29.5,"note":"Meadow country begins."},{"day":4,"place":"Badimalika Temple","altitude_m":4200,"lng":81.42,"lat":29.56,"note":"The temple on the ridge, and the whole Saipal range north."},{"day":5,"place":"Nyaulpani","altitude_m":3200,"lng":81.44,"lat":29.5,"note":"Back down."},{"day":6,"place":"Martadi","altitude_m":1400,"lng":81.51,"lat":29.37,"note":"Out."},{"day":7,"place":"Nepalgunj","altitude_m":150,"lng":81.62,"lat":28.05,"note":"Long drive."},{"day":8,"place":"Kathmandu","altitude_m":1400,"lng":85.324,"lat":27.717,"note":"Fly."}]'::jsonb, '[{"m":1,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":2,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."},{"m":3,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":4,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":5,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":6,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":7,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":8,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":9,"crowds":3,"weather":4,"cost":3,"note":"Good walking, fewer people."},{"m":10,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":11,"crowds":1,"weather":1,"cost":2,"note":"Monsoon — cloud, leeches, landslides."},{"m":12,"crowds":1,"weather":2,"cost":2,"note":"Cold and quiet; passes may be closed."}]'::jsonb, '[{"q":"When is the pilgrimage?","a":"Janai Purnima in August. Tens of thousands walk up over a few days; the meadows become a temporary town."},{"q":"Is it walkable outside the festival?","a":"Yes, and it is beautiful and empty from May to September. Snow closes the high meadow the rest of the year."}]'::jsonb)
on conflict (slug) do update set
  region = excluded.region, typical_days = excluded.typical_days,
  max_altitude_m = excluded.max_altitude_m, difficulty = excluded.difficulty,
  season_months = excluded.season_months, distance_km = excluded.distance_km,
  summary = excluded.summary, start_point = excluded.start_point,
  end_point = excluded.end_point, sort = excluded.sort,
  day_stops = excluded.day_stops, month_profile = excluded.month_profile,
  faq = excluded.faq;


-- Hero photos: reuse what we have per region, so no route page renders a hole.
update public.routes set hero_photo_url = '/img/routes/' || slug || '.jpg'
where hero_photo_url is null
  and slug in ('everest-base-camp','annapurna-circuit','langtang-valley',
               'manaslu-circuit','gokyo-lakes','mardi-himal');

update public.routes r set hero_photo_url = coalesce(
  (select r2.hero_photo_url from public.routes r2
    where r2.region = r.region and r2.hero_photo_url is not null limit 1),
  '/img/hero.jpg')
where r.hero_photo_url is null;
